/// <summary>
/// pickup advice report controller
/// </summary>
public class METPickupAdviceReportController extends SRSReportRunController
{


}

Method.Source:
/// <summary>Constuct new object</summary>
/// <returns>New Controller Object</returns>
public static METPickupAdviceReportController construct()
{
    return new METPickupAdviceReportController();
}

/// <summary>
/// The main method of the batch job.
/// </summary>
/// <param name = "_args">The arguments passed by the caller object.</param>
public static void main(Args _args)
{
    METPickupAdviceReportContract   contract;

    METPickupAdviceReportController controller = METPickupAdviceReportController::construct();

    if (_args && _args.menuItemName() == menuItemOutputStr(METPickupAdviceReport))
    {
        controller.parmReportName(ssrsReportStr(METPickUpAdvicesReport, ReportPickupAdvice));
    }
    else
    {
        controller.parmReportName(ssrsReportStr(METPickUpAdvicesReport, Report));
    }

    controller.parmArgs(_args);
    if (_args && _args.record() && _args.record().TableId == tableNum(SalesTable))
    {
        SalesTable salesTable = _args.record();

        if (salesTable.SalesType == SalesType::ReturnItem)
        {
            SalesLine salesLine;
            METCustParameters metCustParameters;

            select firstonly DispositionCodeRegistration from metCustParameters;

            select firstonly RecId from salesLine
                where salesLine.SalesId == salesTable.SalesId
                   && salesLine.ReturnDispositionCodeId == metCustParameters.DispositionCodeRegistration;

            if (!salesLine.RecId)
            {
                return;
            }
        }

        contract = new METPickupAdviceReportContract();
        contract.parmRecId(salesTable.RecId);
        contract.parmRMANumber(salesTable.ReturnItemNum);

        controller.parmReportContract().parmRdpContract(contract);
        controller.parmShowDialog(false);
    }

    controller.startOperation();
}
